/* Original small exercises. Real model training is explicitly a local lab. */
const modelTracks=[
 ['ai-math','AI 数学与数据起步','∑','从平均数、向量到变化率；先算小数字，再看公式。','算出简单预测误差并解释一次参数更新','https://developers.google.com/machine-learning/crash-course'],
 ['neural','神经网络 · 从一个神经元开始','◎','用普通 Python 拆开权重、偏置、激活、损失与梯度。','手算前向传播，运行一个会降低误差的小模型','https://docs.pytorch.org/tutorials/beginner/basics/intro.html'],
 ['deep','深度学习与 PyTorch','▦','先认识张量和训练循环，再在本机跑一个小网络。','解释训练、验证、保存和重载的完整流程','https://docs.pytorch.org/tutorials/beginner/basics/quickstart_tutorial.html'],
 ['nlp','NLP 与语言模型基础','文','从文字变数字开始，认识词元、向量、注意力和生成。','解释语言模型处理文本的主要步骤与限制','https://huggingface.co/learn/llm-course/chapter1/1'],
 ['deployment','大模型部署与运行','▣','分清模型文件和服务，从内存估算到本机接口验收。','独立记录一次本机推理部署与故障定位','https://docs.ollama.com/quickstart'],
 ['finetuning','模型微调与评估','↻','先做数据与基线，再理解监督训练、验证和回滚。','设计可复现的小样本微调实验并评价收益','https://huggingface.co/docs/transformers/training'],
 ['lora','LoRA · 低秩适配','AB','用小矩阵理解冻结底座与可训练增量，再读真实配置。','解释 LoRA 参数量、训练边界与适配器加载','https://arxiv.org/abs/2106.09685'],
 ['qlora','QLoRA · 量化后的适配训练','4b','从精度和舍入误差出发，理解显存与兼容性限制。','区分量化与微调，完成条件明确的实验设计','https://huggingface.co/docs/peft/developer_guides/quantization'],
 ['knowledge-graph','知识图谱 · 实体与关系','⋈','把自然语言整理为带来源的事实，练查询、消歧和更新。','实现小图查询，并解释事实的来源与时效','https://www.w3.org/TR/rdf11-primer/'],
 ['rag','RAG · 可追溯的知识问答','⌕','从文档切块和检索，走到引用、拒答、权限与评估。','搭建可测试的小型检索管道并区分召回与生成问题','https://arxiv.org/abs/2005.11401']
];
for(const [id,name,symbol,desc,outcome,source] of modelTracks)TRACKS.push({id,name,symbol,desc,outcome,source,color:'#397e79',tint:'#eaf7f3',prereq:'先完成本模块“出发前”与先修导航中的基础课'});
function modelGuide(track,num,title,concept,example,explain,steps,question,options,answer,extra={}){
 const id=track+'-'+String(num).padStart(2,'0');
 guide({id,track,title,minutes:20,conceptOnly:!extra.localLab,intro:'本课只解决一个问题：'+title+'。先预测示例，再做一个小改动，最后解释原因。',concept,example,explain,steps,
 checks:['我完成了本课步骤，留下输入与结果记录','我能解释结果，并说明这个示例不能证明什么'],
 quiz:{q:question,options,answer,explanation:explain},
 mini:{type:'choice',prompt:question,options,answer},hint:explain,
 reflection:'换一个输入或假设，结果会怎样？写下你的预测与理由。',...extra});
}
function modelPython(track,num,title,concept,example,explain,steps,starter,solution,test,extra={}){
 add({id:track+'-'+String(num).padStart(2,'0'),track,title,minutes:20,intro:'用普通 Python 看清一个原理。本练习不下载大模型，也不消耗模型 API 额度。',concept,example,explain,steps,starter,solution,test,hint:explain,reflection:'先解释每个中间结果，再换一个输入验证；通过代码检查不代表已经掌握整门技术。',...extra});
}
modelPython('ai-math',1,'平均数：把一组数概括成一个数','总和除以个数得到平均数。空列表没有通常意义下的平均数，本课约定返回 None；先判断空，再做除法。','(2 + 4 + 6) / 3 = 4','sum(xs) 求和，len(xs) 数项数。/ 是除法。空列表长度是0，直接除会出错。',['完成 mean(xs)，空列表返回 None。','预测 [2,4,6] 的结果再运行。','新增 [-2,2] 并解释结果。'],'def mean(xs):\n    return None\n','def mean(xs):\n    if not xs:\n        return None\n    return sum(xs) / len(xs)\n','assert mean([2,4,6]) == 4\nassert mean([-2,2]) == 0\nassert mean([]) is None');
modelPython('ai-math',2,'向量与点积：对应相乘再相加','向量先理解成按顺序排列的一组数字。点积把对应位置相乘后求和；两组长度必须相同。','[2, 3] · [4, 5] = 2×4 + 3×5 = 23','zip 把同位置配成一对。先检查长度，否则 zip 会在短的一组结束时静默停止。我们约定空向量点积为0。',['写 dot(a,b)，长度不同抛出 ValueError。','用纸算示例，然后运行。','用 [1,0] 与 [9,8] 说明哪个位置起作用。'],'def dot(a, b):\n    return 0\n','def dot(a, b):\n    if len(a) != len(b):\n        raise ValueError("length mismatch")\n    return sum(x*y for x,y in zip(a,b))\n','assert dot([2,3],[4,5])==23\nassert dot([1,0],[9,8])==9\nassert dot([],[])==0\ntry:\n    dot([1],[1,2])\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("must reject different lengths")');
modelGuide('ai-math',3,'矩阵与形状：先数行和列','矩阵是排列成行列的数。形状 (2,3) 表示2行3列；不是数字23。矩阵相乘要求左边列数等于右边行数。','A: 2行3列\nB: 3行1列\nA×B: 2行1列','可以把每行理解为一个样本、每列理解为一种特征。相乘时输出每个格子由一行与一列做点积得到。',['画2行3列空格，填入1到6。','画3行1列，填入1、0、0。','算出结果第一行是1、第二行是4。'],'(2,3) 与 (3,1) 相乘，结果形状？',['(3,3)','(2,1)','(1,2)'],1);
modelGuide('ai-math',4,'概率、频率与数据偏差','频率是观察到的比例；概率模型是对不确定性的描述。小样本频率不等于长期概率，数据来源也会影响结果。','10条评论里8条正面 → 样本正面比例0.8','这只能描述收集到的10条。若只收集点赞最多的评论，样本就有偏差；不能据此断言所有用户80%满意。',['画10个格子，标8个正面。','计算8/10。','写出两种会使样本不代表全体的收集方式。'],'这10条评论足以证明全部用户满意度80%吗？',['足以','不足以，要检查采样与不确定性'],1);
modelGuide('ai-math',5,'变化率：参数动一点，误差怎样变','函数把输入映射为输出。导数描述局部变化率；先用相邻两个点的差来理解，不要求先背微积分。','f(w)=w²\nf(2)=4，f(2.01)=4.0401\n变化率近似=(4.0401-4)/0.01=4.01','在 w=2 附近，w 增大时平方增大。精确导数是2w，因此该点为4。梯度下降沿局部上升方向的反方向走一小步；步子太大仍可能变差。',['用计算器核对三个数。','从2减去0.1，算1.9²。','从2减去5，算(-3)²，解释大步为何失败。'],'梯度下降是否保证任意步长都降低损失？',['是','否，步长与函数形状有关'],1);
modelPython('neural',1,'一个神经元：加权、偏置、输出','权重决定输入影响的大小，偏置是额外可调的常数。本课先用一个输入：y=w*x+b。','x=3, w=2, b=1 → y=7','x 是观测输入；w 和 b 是模型参数。预测时按公式算；训练时才根据误差调整参数。',['完成 predict(x,w,b)。','分别只改 x、w、b，预测结果。','说明输入与参数的区别。'],'def predict(x, w, b):\n    return 0\n','def predict(x, w, b):\n    return w*x+b\n','assert predict(3,2,1)==7\nassert predict(0,2,1)==1\nassert predict(-2,3,0)==-6');
modelPython('neural',2,'激活函数：给网络一个转折','ReLU 把负数变成0，非负数保持原值。多层线性变换若没有非线性，仍可合并成一个线性变换。','ReLU(-2)=0\nReLU(3)=3','max(0,x) 选两者较大值。这里不讨论复杂激活，只观察转折使模型能表示不同区域的不同规则。',['实现 relu(x)。','测试负数、零和正数。','把输出画在横轴x、纵轴y的纸上。'],'def relu(x):\n    return x\n','def relu(x):\n    return max(0,x)\n','assert relu(-2)==0\nassert relu(0)==0\nassert relu(3)==3');
modelPython('neural',3,'损失：给预测的错误打分','平方误差等于 (预测-真实)²。符号被平方消除，偏差越大通常罚得越重。损失函数必须与任务一致。','预测5，真实3 → (5-3)²=4','本课是一个样本的平方误差。它不等于分类准确率，也不等于现实业务代价。训练通过降低选定损失改善模型。',['完成 squared_error。','比较预测1与5、真实3的损失。','解释为什么两者损失相等。'],'def squared_error(pred, target):\n    return 0\n','def squared_error(pred, target):\n    return (pred-target)**2\n','assert squared_error(5,3)==4\nassert squared_error(1,3)==4\nassert squared_error(3,3)==0');
modelPython('neural',4,'第一次训练：沿梯度改权重','模型 y=w*x，损失 (w*x-target)²。链式法则把损失对预测的变化与预测对权重的变化相乘，得到梯度 2*(w*x-target)*x。','x=1,target=2,w=0\ngrad=-4\nw_new=0-0.1*(-4)=0.4','训练不是直接把正确答案抄入参数。每步先预测、算梯度，再 w-lr*grad。lr 是学习率，即每步走多大。',['实现 step(w,x,target,lr)。','核对第一次得到0.4。','重复20次观察接近2；说明这只是一个参数的小例子。'],'def step(w, x, target, lr):\n    return w\n','def step(w, x, target, lr):\n    grad=2*(w*x-target)*x\n    return w-lr*grad\n','assert abs(step(0,1,2,0.1)-0.4)<1e-9\nassert step(2,1,2,0.1)==2\nw=0\nfor _ in range(20):\n    w=step(w,1,2,0.1)\nassert (w-2)**2<0.001');
modelGuide('neural',5,'多层与反向传播：误差往回传','前向传播逐层算预测；反向传播用链式法则算各参数的梯度；优化器根据梯度更新参数。梯度不是参数的新值。','输入 → 第一层 → 激活 → 第二层 → 损失\n参数 ← 梯度 ← 链式法则 ← 损失','隐藏层是输入输出之间的计算层，并不是隐藏资料库。反向传播计算变化率；参数更新是随后单独的一步。',['画前向箭头和反向箭头，用两种颜色。','标出哪一步真正改参数。','用本课前四节说明每个方框里在算什么。'],'反向传播主要得到什么？',['训练完成的保证','各参数的梯度','新的原始数据'],1);
modelGuide('deep',1,'张量、批次与设备','张量是带形状的多维数值容器。一个批次是一次处理的多条样本。CPU与GPU是运算设备，参与同一运算的数据与模型须放在兼容设备。','4个样本，每个样本3个特征 → shape=(4,3)','第一个4不是层数。读报错先打印形状与设备。大批次通常使用更多内存；GPU不是所有小实验的必要条件。',['画4行3列。','每行标一个样本。','假设每个样本增加1个特征，写出新形状。'],'(4,3) 批次中每个样本有几个特征？',['4','3','12'],1);
modelGuide('deep',2,'训练、验证、测试不能混用','训练集参与参数更新；验证集用于选择设置；测试集留到方案确定后做最终评估。相近或重复样本跨集合会造成泄漏。','用户A的记录 → 全部放训练集\n用户B的记录 → 验证集\n用户C的记录 → 测试集','按行随机切分不一定安全。例如同一病人或同一篇文档的多个片段会互相泄漏。要按业务实体或时间划分。',['把9条属于3个用户的记录写在纸上。','按用户分组切分，保证同一用户不跨集合。','解释为什么不能看到测试结果后不停调参。'],'测试集表现差就继续用它选参数，还是测试集吗？',['仍完全独立','已经参与决策，失去独立评估意义'],1);
modelGuide('deep',3,'训练循环逐行读','zero_grad 清掉旧梯度；前向算输出；loss 算差距；backward 算梯度；step 更新参数。eval 切换部分层的行为，no_grad 关闭梯度记录。','optimizer.zero_grad()\npred = model(x)\nloss = loss_fn(pred, y)\nloss.backward()\noptimizer.step()','这些动作按顺序完成一轮学习。PyTorch 默认累积梯度，所以本课每步清零。model.eval() 本身并不等于关闭梯度计算。',['对照神经网络课给五行分别写中文。','圈出真正修改参数的行。','解释省略清零为什么会累积旧梯度。'],'哪一行真正更新参数？',['loss.backward()','optimizer.step()','pred = model(x)'],1);
modelGuide('deep',4,'本机实验：训练、保存、重载小模型','先用 CPU 和小型合成数据验证流程，无需 GPU 与模型下载。合成任务不代表真实世界能力。','python -m pip install torch\npython labs/tiny_torch.py','安装前先完成工程课的虚拟环境。附带脚本逐步训练 y=2x+1，再保存参数并重载验证一致性。安装包较大，按官方安装选择器确认系统支持；不要把命令输入本站 Python 编辑区。',['从课程目录下载本机实验包，解压后打开 README。','创建并激活虚拟环境，按 PyTorch 官方入口选安装命令。','运行 tiny_torch.py，记录初始/最终损失和重载误差。','把训练次数改小，对照结果；未达到断言时解释原因，不删断言。'],'页面知识题通过能证明本机模型已训练成功吗？',['能','不能，需要本机运行日志'],1,{localLab:true});
modelGuide('deep',5,'过拟合与排查顺序','训练越来越好而验证变差可能是过拟合。也要检查数据泄漏、评估模式、标签质量和分布变化；单凭一条曲线不能唯一定位原因。','轮次   训练损失   验证损失\n1      0.8       0.9\n5      0.3       0.5\n20     0.05      1.2','增加训练并不总能改善新数据。先检查划分与评估代码，再比较早停、更多有效数据、正则化等方案；每次改变一项才好解释。',['找出验证损失最低的轮次。','写下两个可能原因与要看的证据。','选一个方案并写对照实验，不直接宣称解决。'],'表中按验证损失选哪次检查点？',['第20轮','第5轮','只看训练损失'],1);
modelPython('nlp',1,'从文本到词元：先做玩具分词器','词元是模型处理的文本单位，不一定是完整汉字或单词。本课按空格切词只是教学规则，不能代替真实模型的分词器。','"red  blue" → ["red", "blue"]','str.split() 会合并连续空白，空字符串返回空列表。中文通常没有空格，不能把这个例子当成中文分词系统。',['实现 tokens(text)，统一小写再切分。','测试连续空格和空输入。','解释“北京欢迎你”为什么不会自动分成词。'],'def tokens(text):\n    return []\n','def tokens(text):\n    return text.lower().split()\n','assert tokens("Red  BLUE")==["red","blue"]\nassert tokens("")==[]\nassert tokens("北京欢迎你")==["北京欢迎你"]');
modelPython('nlp',2,'词表与未知词','词表把词元映射成整数ID。ID是编号，大小不代表语义距离。没收录的词在这个教学例子中用0表示。','词表 red:1, blue:2\n输入 red green → [1,0]','字典 get(key,0) 在键不存在时返回0。真实模型必须使用与权重匹配的分词器，不能随意换词表。',['完成 encode(words,vocab)。','用未出现的 green 测试。','解释编号1与2不意味着两个词意思接近。'],'def encode(words, vocab):\n    return []\n','def encode(words, vocab):\n    return [vocab.get(w,0) for w in words]\n','assert encode(["red","green"],{"red":1})==[1,0]\nassert encode([], {})==[]');
modelGuide('nlp',3,'Embedding：编号变向量','Embedding 将词元或文本映射为数值向量。向量的相似性由模型与任务决定，不是真理判定。不同模型产生的向量通常不能直接混查。','词元ID 2 → 查表 → [0.2, -0.4, 0.7]','编号用来定位，向量承载训练得到的表示。句子向量可用于检索，但相似文本可能观点相反；仍要核对原文。',['画词表与向量表两张表。','沿ID2找到对应一行。','写一对词相近但意思相反的句子，解释检索的局限。'],'语义相似分数高能证明事实正确吗？',['不能','能'],0);
modelGuide('nlp',4,'注意力：按相关程度汇总信息','注意力为不同位置分配权重并汇总信息。Query寻找什么、Key用来匹配、Value提供被汇总的内容。权重通常经过 softmax 归一化。','两个 Value: 10 和 20\n注意力权重: 0.25 和 0.75\n汇总: 0.25×10+0.75×20=17.5','这个一维算例只说明加权汇总。真实 Transformer 有向量投影、多头、位置表示与多层结构；注意力权重本身也不是完整因果解释。',['手算17.5。','把权重交换，算12.5。','说明若位置顺序被完全丢掉，“猫追狗”和“狗追猫”会有什么问题。'],'权重0.25和0.75汇总10和20等于？',['30','17.5','7.5'],1);
modelGuide('nlp',5,'下一个词元、上下文与幻觉','自回归语言模型逐步预测下一个词元。上下文有长度限制；流畅的续写不保证可靠事实。temperature 控制采样分布，低温也不能保证真实。','已有文本 → 下个词元概率 → 选择词元 → 加回上下文 → 继续','生成不是从一个完整答案库取出保证正确的答案。需要事实时应提供可核查证据；需要结构时还要程序验证。',['画生成循环。','写一个资料不足但容易猜测的问题。','为这个问题设计“缺证据则拒答”的规则。'],'temperature=0 是否保证回答真实？',['不保证','保证'],0);
modelPython('deployment',1,'参数量与存储：先估算下限','一个参数用多少位存储，会影响权重体积。8位=1字节，GiB=1024³字节。这里只估算原始权重，不含缓存、量化元数据与运行开销。','10亿参数 × 16位 / 8 ≈ 2GB（十进制）','模型实际运行还要为 KV cache、中间计算、并发等留空间。权重能放下不等于训练或长上下文能跑。',['写 weight_gib(n,bits)。','比较16位与4位的理想权重体积。','在笔记注明这是下限，不能据此承诺显存够用。'],'def weight_gib(n, bits):\n    return 0\n','def weight_gib(n, bits):\n    return n*bits/8/(1024**3)\n','assert weight_gib(1024**3,8)==1\nassert weight_gib(1024**3,4)==0.5\nassert weight_gib(0,16)==0');
modelGuide('deployment',2,'模型卡、文件与许可证','模型卡说明用途与限制；权重是学到的参数；分词器处理文字；配置描述结构。部署前记录版本和许可证，确认资源与预期用途适配。','部署清单：模型ID / 精确版本 / 许可证 / 文件大小 / 运行方式 / 测试问题','同名不同版本可能行为不同。不要把下载成功当成运行成功；也不要随意允许仓库执行远程代码。优先选择自己能解释的加载方式。',['打开官方模型目录，先读模型卡，不下载大文件。','填清单，未知项写“待确认”。','写下磁盘不足与内存不足的不同表现。'],'只保存模型名字足以复现实验吗？',['足够','不够，还需版本、配置与环境'],1);
modelGuide('deployment',3,'本机推理服务：进程、端口与请求','Ollama 可运行本机模型并提供 HTTP 接口。本机服务通常通过 localhost:11434 访问；localhost 指当前电脑。先选符合机器资源的本地模型。','ollama list\n# 查看已经下载的模型，记下完整名称\n# 然后运行实验包 local_chat.py，并按提示输入该名称','先从官方入口安装并启动应用，选本地模型；下载体积以模型页面为准。实验脚本只访问本机，不需要API密钥。若没有已下载模型，先读资源要求再决定。',['按官方安装说明完成 Ollama 安装，确认选择本地运行。','使用 ollama list 查看名称；没有模型先选择资源合适的模型下载。','执行 python labs/local_chat.py，输入完整模型名。','记录响应、用时、模型名称；换一个问题重复。'],'localhost 指向什么？',['互联网上任意模型','运行请求程序的这台电脑'],1,{localLab:true});
modelGuide('deployment',4,'部署验收：跑起来只是第一步','验收包括启动、错误处理、超时、并发、资源和访问控制。学习实验仅绑定本机；公开服务还需要鉴权、限流、审计与隔离。','故障：连接拒绝 / 模型不存在 / 超时\n证据：服务状态 / 模型列表 / 耗时与日志','连接拒绝先看进程和端口；模型不存在先核对完整名称；超时再看资源和输入长度。不要用关掉安全设置当作通用修复。',['故意输入不存在的模型名，记录错误。','停止本机服务后再请求，比较错误。','恢复服务复测；画请求路径并写明未完成的生产验收项。'],'服务超时最合理的第一步？',['无限提高超时时间','记录输入、耗时、资源与服务日志后定位'],1);
modelGuide('finetuning',1,'提示、RAG 与微调解决什么问题','提示改变本次输入；RAG检索外部资料放进上下文；微调通过训练改变参数。经常更新的事实通常先考虑检索，稳定格式或行为再评估微调。','需求A：回答本周更新的产品文档\n需求B：稳定输出固定业务格式','方法可以组合。微调不会自动成为精确数据库；先建立简单基线，比较是否真的需要训练。格式要求也应先试提示与结构验证。',['为A、B分别列一个不训练的基线。','写什么时候基线不够。','列出比较方案需要的相同测试问题。'],'每天变化的库存数量应该直接靠微调记住吗？',['不应，先查实时数据或检索','应该每天训练代替数据库'],0);
modelGuide('finetuning',2,'训练样本：输入、目标与数据许可','监督微调用输入与期望回答组成样本。质量、覆盖范围与许可比盲目增加数量重要；真实隐私和密钥不能成为练习数据。','{"input":"把任务设为完成", "target":"{\"done\": true}"}','训练样本必须与推理任务对应。保持格式一致，去重，再按来源分组切分；不要让同一个问题的改写跨训练和测试集合。',['写3条自己编造、无隐私的样本。','检查输入是否足够决定目标。','标记重复与歧义，留出从没用于训练的测试题。'],'样本数多但目标互相矛盾，会更可靠吗？',['不会','一定会'],0);
modelGuide('finetuning',3,'学习率、批次、轮次与累积','学习率是更新幅度；批次是一次处理的样本数；epoch 是遍历训练集一轮；梯度累积可以多次前向反向后再更新。','微批次2 × 累积4 × 单设备1 = 有效批次8','更大有效批次并不保证更好。上下文长度、激活和优化器状态都影响内存。记录随机种子、数据版本、包版本和设置，才能比较。',['用8条样本画4个微批次。','标出第4次后进行参数更新。','写明这里是假设单设备，不能随意套到其他配置。'],'梯度累积4次时每个微批次都做参数更新吗？',['是','不是，通常到累积边界再更新'],1);
modelGuide('finetuning',4,'基线对照、遗忘与发布门槛','同时比较任务指标、通用能力、成本和失败案例。训练损失下降不代表新题更好；微调也可能损害原有能力。','同一测试集：底座 → 微调模型\n记录：正确/格式合法/拒答/耗时/错误类型','事先定义通过门槛，不根据结果临时改规则。若改善不足或出现严重退化，保留底座与旧适配器用于回滚。',['写10道从未训练过的题，含资料不足与格式边界。','同条件运行两种模型并保留原始回答。','逐项评分，报告样本量与未覆盖范围。'],'只报告训练损失降低足以证明微调有效吗？',['不够，要比较未见数据与回归任务','足够'],0);
modelGuide('lora',1,'低秩：大矩阵增量拆成两个小矩阵','LoRA 冻结基础权重W，训练较小的A、B，用缩放后的BA作为权重增量。秩r决定这两个小矩阵的中间维度。','W: 4×6 = 24个参数\nA: 2×6，B: 4×2 → 12+8=20个参数','小例子节省不明显；大矩阵且秩远小于维度时才明显减少可训练参数。基础模型依然要加载，不是只存20个数就能独立推理。',['画W、A、B形状，验证BA为4×6。','把r从2改1，算6+4=10。','说明减少的是哪部分参数，哪些仍存在。'],'适配器能脱离匹配底座独立完成同样推理吗？',['能','通常不能'],1);
modelPython('lora',2,'计算可训练参数量','对 out×in 的线性权重，秩r的A、B合计 r*(in+out) 个参数。本课不计算偏置等其他可训练模块。','in=100,out=200,r=4 → 1200','基础权重是20000个数，适配器是1200个。实际模型有多个目标层，需逐层求和；不能把这个局部比值当作整机显存节省率。',['完成 lora_count。','对比完整矩阵的数量。','改变r观察数量线性变化。'],'def lora_count(in_features, out_features, rank):\n    return 0\n','def lora_count(in_features, out_features, rank):\n    return rank*(in_features+out_features)\n','assert lora_count(100,200,4)==1200\nassert lora_count(6,4,2)==20\nassert lora_count(6,4,1)==10');
modelGuide('lora',3,'配置与冻结：读懂真实代码','PEFT 的 LoraConfig 指定秩、缩放、目标模块等设置，get_peft_model 注入适配器。先确认模型结构与目标层名称，再检查可训练参数。','from peft import LoraConfig, get_peft_model\nconfig = LoraConfig(r=8, lora_alpha=16, target_modules=["q_proj", "v_proj"], task_type="CAUSAL_LM")\n# adapted = get_peft_model(base_model, config)','此片段展示配置，不是完整训练脚本。q_proj/v_proj 并非所有模型都有。base_model 需要先按官方说明加载；随后打印可训练参数，确认底座冻结。',['圈出r、alpha、目标层三项。','在选定模型结构中查找目标名称，不凭名字猜。','记录可训练数量与总数量；不匹配时先停止排查。'],'目标层名可以不看模型结构照抄吗？',['不可以','可以，所有模型相同'],0,{source:'https://huggingface.co/docs/peft/quicktour'});
modelGuide('lora',4,'保存、重载与小型可运行实验','适配器应与基础模型ID、版本、分词器、训练配置一起记录。用相同输入对比保存前后输出，才能检查重载。','python labs/lora_toy.py','附带实验仅用 Python 标准库训练一个秩1矩阵增量，展示冻结底座、损失下降和保存重载；它不是大语言模型微调。真实模型需要另行安装PEFT和匹配模型。',['运行实验包中的 lora_toy.py。','核对底座没有改变，损失下降，重载预测一致。','解释其中A和B的形状，再尝试改变目标并观察秩1的限制。'],'玩具矩阵实验成功是否证明真实大模型已微调？',['是','否，只验证这个原理实验'],1,{localLab:true});
modelGuide('qlora',1,'量化先从舍入理解','量化用更少位数表示数值，会引入误差。教学中把1.26舍入为1.3方便理解；真实4位量化不是简单统一保留一位小数。','原值1.26 → 舍入1.3 → 误差0.04','位宽是表示预算，计算时可能使用更高精度。量化降低权重存储需求，也可能影响输出，必须重新评估。',['把1.26与-0.24保留一位小数。','计算两个误差的绝对值。','解释“位数更少”与“完全没损失”的区别。'],'4位权重意味着所有计算也只用4位吗？',['是','不是，存储与计算精度可以不同'],1);
modelGuide('qlora',2,'QLoRA 的两条线','QLoRA 在量化冻结的底座上训练低秩适配器。原论文结合NF4、双重量化、分页优化器等技术；不是把LoRA文件再压缩一下。','冻结的量化底座 + 可训练LoRA → 输出 → 损失 → 更新适配器','量化与可训练参数是不同维度。优化器状态、激活、上下文长度依然占内存，不能只用权重体积估算训练上限。',['用两种颜色标底座与适配器。','在箭头上标明梯度走向与真正更新的部分。','写出三个除权重外的内存来源。'],'QLoRA 通常更新哪部分？',['所有4位底座权重','适配器等明确允许训练的参数'],1,{source:'https://arxiv.org/abs/2305.14314'});
modelGuide('qlora',3,'环境检查与配置阅读','真实QLoRA依赖模型、PyTorch、量化后端与硬件兼容性。先核对官方支持矩阵，记录版本，再做最小加载，最后才训练。','from transformers import BitsAndBytesConfig\nconfig = BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type="nf4")\n# 加载模型后，再用 prepare_model_for_kbit_training 准备训练','这里只解释配置。它不是可独立运行的脚本，也没有验证你的显卡。不能承诺任意Windows电脑都能跑；不支持时继续做原理实验，避免盲目安装驱动或购买GPU。',['列出自己的系统、Python、PyTorch、设备和可用显存。','对照官方量化后端支持说明，把未知项标出来。','写加载→准备k位训练→注入适配器→小批次训练→重载评估的顺序。'],'环境不支持，最合适的下一步？',['盲目改驱动','核对兼容矩阵并选择受支持环境或原理实验'],1);
modelGuide('qlora',4,'显存故障与公平比较','显存不足可能在加载、前向、反向或保存时出现。分别记录峰值与阶段；改变上下文长度、批次或检查点策略后重测。','对照表：LoRA / QLoRA\n相同：模型、数据、测试题\n记录：设置、峰值内存、用时、质量、失败案例','更省显存不意味着总是更快或质量必然相同。不同硬件与量化内核差异较大；没有实测就填“未测试”，不复制论文数字当本机结果。',['设计两组条件可比的实验。','加入一次空输入与长输入。','写“尚未进行GPU训练”，直到有自己的原始日志才更新状态。'],'论文的显存数字可以直接当自己机器的结果吗？',['不可以','可以'],0);
modelGuide('knowledge-graph',1,'实体、关系与三元组','实体是可区分的对象，关系连接对象。三元组写成主语、关系、宾语；名字只是标签，稳定ID帮助区分同名实体。','(person:1, works_at, org:7)\n标签：小林，任职于，甲公司','同名小林可能是两个人。先确定实体身份，再保存关系；在事实旁附来源和时间，避免把猜测变成长期事实。',['用三个自己编造的实体画小图。','给每个实体不同ID。','加一条关系并注明示例来源，不放真实隐私。'],'同名实体是否应该自动合并？',['是','否，先依据身份信息消歧'],1);
modelPython('knowledge-graph',2,'查询一跳邻居','一跳查询找出从某实体直接出发、指定关系连接到的对象。这里用三元组列表，不需要先安装图数据库。','[("a","knows","b"),("a","likes","c")]\n查询a的knows → ["b"]','依次解包s,r,o；同时检查主语和关系。返回结果按原始顺序；这个小实现保留重复事实，去重是下一步设计选择。',['实现 neighbors(triples,subject,relation)。','测试同主语不同关系。','查询不存在的实体，应返回空列表。'],'def neighbors(triples, subject, relation):\n    return []\n','def neighbors(triples, subject, relation):\n    return [o for s,r,o in triples if s==subject and r==relation]\n','data=[("a","knows","b"),("a","likes","c"),("x","knows","d")]\nassert neighbors(data,"a","knows")==["b"]\nassert neighbors(data,"missing","knows")==[]');
modelGuide('knowledge-graph',3,'抽取、消歧与事实更新','从文本抽取的关系是候选事实，必须核对证据。同名、否定、时间变化、来源冲突都会让机械抽取出错。','原文：小林2024年离开甲公司。\n错误抽取：小林目前任职于甲公司','三元组不自动携带“目前”。保存有效时间、来源片段与审核状态；冲突时保留冲突并标记，而不是静默覆盖。',['标出原文中的否定或时间信息。','设计 source、valid_from、valid_to、review_status 字段。','写出人工核查需要看的原文。'],'文本里出现人名和公司名就能认定现任职关系吗？',['不能','能'],0);
modelGuide('knowledge-graph',4,'多跳、环与图谱问答','多跳查询沿关系继续走。图可能有环，遍历时记录已访问节点并限制深度。图回答关系问题，原文提供语境与证据。','a认识b，b认识c，c认识a\n从a走两跳：a→b→c','不加限制会绕圈。图谱与向量检索可以组合，但检索路径存在不等于关系可信，仍要检查来源和时间。',['画环图并手动走两跳。','记录visited集合和最大深度。','为一条问答画“问题→实体→关系→原文证据”链。'],'防止遍历环最需要什么？',['无限递归','已访问记录与深度或预算限制'],1);
modelPython('rag',1,'切块：给片段保留身份','长文档分成片段，便于检索与引用。本课按固定字符数切块，无重叠；真实任务还应考虑段落、表格和token预算。','"abcdef"，size=2 → ["ab","cd","ef"]','range(0,len(text),size) 生成起点，切片取一段。size<=0应拒绝。空文档返回空列表。之后还要保存doc_id、chunk_id、版本等元数据。',['实现 chunks(text,size)。','测试尾部不足一块。','解释为什么真实检索不能只保存片段文字。'],'def chunks(text, size):\n    return []\n','def chunks(text, size):\n    if size<=0:\n        raise ValueError("size must be positive")\n    return [text[i:i+size] for i in range(0,len(text),size)]\n','assert chunks("abcde",2)==["ab","cd","e"]\nassert chunks("",2)==[]\ntry:\n    chunks("x",0)\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("invalid size")');
modelPython('rag',2,'先做可解释的关键词检索','先用关键词重叠数量作教学基线，再讨论向量检索。按空格分词并转小写；分数相同按原文顺序，完全不匹配返回空列表。','问题 red\n文档 red blue / green → 只取第一篇','这不是语义检索，也不能处理没有空格的中文分词。基线越透明，越容易验证数据流和评估后续改进。',['实现 retrieve(query,docs)，返回有匹配的文档索引。','按匹配词数从高到低排序。','测试无匹配、并列和大小写。'],'def retrieve(query, docs):\n    return []\n','def retrieve(query, docs):\n    terms=set(query.lower().split())\n    scores=[(len(terms & set(d.lower().split())),i) for i,d in enumerate(docs)]\n    return [i for score,i in sorted(scores,key=lambda p:(-p[0],p[1])) if score>0]\n','assert retrieve("red",["red blue","green"])==[0]\nassert retrieve("red blue",["red","BLUE red","green"])==[1,0]\nassert retrieve("none",["red"])==[]\nassert retrieve("red",["red","red"])==[0,1]');
modelGuide('rag',3,'向量、混合检索与重排','向量检索寻找表示相似的片段；关键词检索擅长精确名称；混合检索组合候选；重排模型进一步评估问题与候选的相关性。','文档→切块→向量化→索引\n问题→同一向量模型→召回→重排→上下文','更换Embedding模型后通常要重新生成文档向量。top-k太少可能漏证据，太多可能加入干扰；通过固定评测集调整，而非只试一题。',['画离线建库与在线查询两条线。','标出两处必须匹配的向量模型。','写一个适合关键词与一个适合语义搜索的问题。'],'更换向量模型但保留旧向量，能直接混查吗？',['通常不能，空间不匹配','一定可以'],0);
modelGuide('rag',4,'引用、权限与拒答','RAG把检索到的证据交给生成模型。引用要能回到原文，权限必须在召回与输出链路落实；检索内容是数据，不能覆盖系统指令。','问题 → 允许访问的片段 → 回答与引用\n没有足够证据 → 说明无法确认','引用格式正确不等于内容支持结论。检查每个关键断言与来源是否一致；文档中的“忽略规则”也只是文档内容。不要先检索所有秘密再指望模型保密。',['写一个有证据与一个无证据的问题。','给答案每个事实附片段ID。','加入无权访问文档和恶意指令片段，说明应在哪一层拦住。'],'只有引用编号，就能保证回答有依据吗？',['不能，还需检查原文是否支持结论','能'],0);
modelGuide('rag',5,'评估与本机端到端检索实验','先评估是否找到了正确证据，再评估回答是否忠实、完整、可拒答。召回率关注相关片段有多少被找回；生成评价不能替代检索评价。','python labs/rag_lab.py\n输出检索结果与自动断言；不调用真实大模型','实验包运行切块、带权限过滤的关键词检索、引用与无证据拒答。输出是确定性证据摘录，不伪装成真实LLM生成。接入模型是下一阶段独立扩展。',['运行脚本，阅读每条断言。','修改文档内容或权限，预测检索变化。','设计5个新问题，含过期事实、无证据、越权与恶意指令。','记录检索与生成各自未测的部分。'],'没有找到证据却回答正确，能算检索通过吗？',['能','不能，应单独检查召回'],1,{localLab:true});

// Every new track has a concrete bridge and links to its actual prerequisite courses.
bridge('ai-math','数字、列表与函数',[['样本','一条观察记录'],['特征','用数字表达的一种属性']],'三个房间面积：[10,20,30]','模型先处理数字表达。面积是一种特征，房间是一条样本；单位要一致，缺失值不能悄悄当成0。',['画3行1列并标单位。','指出哪个是样本、哪个是特征。','说出空列表与面积为0的区别。'],'缺失面积与面积为0一样吗？',['不一样','一样'],0);
bridge('neural','规则程序与学习参数',[['参数','可调整的模型数值'],['训练','用样本调整参数'],['推理','固定参数计算新输入']],'规则：价格=单价×数量\n模型：预测=w×输入+b','先理解普通公式，再把w、b视为可调整的数。训练需要评价好坏的损失；不是程序自己无条件懂了世界。',['手算w=2,b=1,x=3。','固定w、b换x。','固定x改变w，区分训练与推理。'],'固定参数处理新输入属于？',['推理','训练'],0);
bridge('deep','库、张量与实验环境',[['库','别人封装好的可复用代码'],['虚拟环境','项目独立使用的一套Python包'],['张量','有形状的数值容器']],'普通Python列表 → PyTorch张量 → 网络计算','先会列表与函数再用框架。安装库解决的是工具可用性，不会自动解决数据和算法错误。CPU可完成小实验，不先要求购买硬件。',['回顾工程课虚拟环境。','画两行两列数字并写shape=(2,2)。','分别举安装错误和计算错误。'],'安装成功等于模型训练正确吗？',['等于','不等于'],1);
bridge('nlp','文字、编码与模型输入',[['字符','文字中的符号'],['编码','字符与字节的转换规则'],['词元','分词器给模型的处理单元']],'文字 → 分词器 → 词元ID → 向量','UTF-8字节、字符数、词元数是不同计数。不能假定一个汉字永远是一个token，长度预算应使用匹配模型的分词器。',['写“你好AI”。','区分显示的字符与文件存储字节。','写下为什么token数需要分词器确认。'],'一个汉字总等于一个token吗？',['不是','是'],0);
bridge('deployment','内存、显存与硬盘',[['硬盘','长期保存下载的文件'],['内存','程序运行中的工作空间'],['显存','GPU使用的工作空间']],'硬盘模型文件 → 加载到工作空间 → 执行推理','下载体积、运行占用、训练占用不同。先调查资源，再选模型；没有显卡仍可学习原理并运行小CPU实验。',['记下可用磁盘与系统内存。','有GPU再记显存，不把系统内存当显存。','写出下载成功后仍可能失败的两种原因。'],'磁盘够放模型就一定能训练吗？',['一定','不一定'],1);
bridge('finetuning','目标、标签与独立评估',[['标签','样本期望的结果'],['基线','用于比较的初始方案'],['数据泄漏','评估信息进入训练或选择过程']],'输入：2+3\n标签：5\n评估：换成未见过的题','训练使用已知答案调整参数，评估应检验未见输入上的行为。重复训练题高分不等于会做新题。',['编3条训练题与2条新题。','把新题单独保存。','解释为什么改写训练题可能仍然泄漏。'],'背对训练题能证明泛化吗？',['不能','能'],0);
bridge('lora','矩阵形状与冻结',[['秩','这里先理解为增量矩阵分解的中间宽度'],['冻结','不更新这部分参数']],'B(4×2) × A(2×6) → 增量(4×6)','先确认矩阵乘法规则；LoRA的A、B不是文本缩写占位，而是真正参与计算的参数矩阵。',['回到数学课复算矩阵乘法形状。','计算A和B一共多少数。','说出冻结后是否仍参与前向计算。'],'冻结的底座仍参与计算吗？',['参与','完全不参与'],0);
bridge('qlora','位宽与近似误差',[['位','二进制表示的一位'],['量化','用有限表示近似数值'],['精度','这里指数值表示的细致程度']],'4位最多有16种比特组合','组合数不等于模型只能输出16个词。量化处理的是参数等数值的表示；模型词表是另一回事。',['计算2×2×2×2。','把连续数轴画成有限刻度。','解释舍入为何有误差。'],'4位模型只能说16个词吗？',['是','不是'],1);
bridge('knowledge-graph','对象身份与方向',[['实体ID','不依赖显示名的稳定标识'],['有向关系','从一个对象指向另一个对象']],'小林 → 管理 → 小周','方向改变含义。关系可以有属性，如开始时间；相同显示名不能证明是同一对象。',['画两个节点与箭头。','反过来读一次，说明意思改变。','给节点加不同ID。'],'反向读管理关系含义相同吗？',['不相同','相同'],0);
bridge('rag','检索与生成分开看',[['检索','从资料中找相关内容'],['生成','根据输入组织或预测输出'],['证据','能够支持结论的原始资料']],'先找手册相关页 → 再依据该页回答','找错页时，写得流畅也无法修复证据缺失。RAG不是把所有文件永久塞进模型参数里；资料库需要维护与权限控制。',['为一道问题选一段支持它的资料。','写出资料未覆盖的另一道问题。','给第二题写一句诚实的拒答。'],'RAG把文档永久写进基础模型参数了吗？',['没有，它通常在请求时提供上下文','写进了'],0);
